function render(){
 const main=$('screen');main.className='screen screen-'+screen;document.body.className=screen==='map'&&atlasExpanded?'atlas-mode':'';
 $('title').innerHTML=screen==='home'?'<span class="wordmark">VI<span>HUB</span><small>COMPANION</small></span>':esc(titleMap[screen]||'VI Hub');
 $('back').innerHTML=screen==='home'?'<img class="brand-icon" src="brand.webp" alt="VI Hub">':icon('back');
 $('back').dataset.action=screen==='home'?'go:more':'back';$('back').setAttribute('aria-label',screen==='home'?'Open menu':'Back');
 $('topSettings').innerHTML=icon(screen==='home'?'search':'settings');$('topSettings').dataset.action=screen==='home'?'go:search':'go:settings';
 $('topSettings').setAttribute('aria-label',screen==='home'?'Search':'Settings');
 const active=({entry:'library',locations:'map',missionIndex:'missions',missionDetail:'missions',completion:'missions',bookmarks:'library',goals:'missions',offline:'more',collectibles:'missions',journal:'more',settings:'more',alerts:'more',search:'library',info:'library',news:'more',article:'more'})[screen]||screen;
 $('nav').innerHTML=[['home','Home','home'],['map','Map','map'],['missions','Progress','mission'],['library','Library','info'],['more','More','more']].map(([s,l,i])=>'<button data-action="go:'+s+'" class="'+(active===s?'active':'')+'"'+(active===s?' aria-current="page"':'')+'><span class="nav-icon">'+icon(i)+'</span><span>'+l+'</span></button>').join('');
 main.innerHTML=({home,news,missions,map,locations,search,info,more,settings,alerts,article,library,entry,collectibles,journal,missionIndex,missionDetail,completion:completionCenter,bookmarks,goals:goalPage,offline:offlineCenter}[screen]||home)();
 if(screen==='map'){initMap();if(mapState==='idle')requestMap();}
}
function home(){
 const done=storyDone(),total=storyTotal,finds=discovered(),known=discoveries().length;
 const brief=catalog.news[0];
 return '<section class="home-hero"><img src="hero.webp" alt=""><span class="hero-vignette"></span><div class="hero-content"><span class="hero-kicker"><i></i> THE LEONIDA COMPANION</span><h2>Your world.<br>Your guide.</h2><p>Explore, discover and keep track.</p>'+action('go:map',icon('map')+' Explore the map '+icon('chevron'),'hero-button')+'</div></section>'
 +sectionTitle('Your progress',action('go:completion','View all','text-link'))
 +'<div class="dashboard"><button class="metric" data-action="go:missions"><span>STORY</span><strong>'+done+'<small> / '+total+'</small></strong><div class="progressrail"><div style="width:'+Math.min(100,done/total*100)+'%"></div></div><small>Tracked missions</small></button><button class="metric" data-action="go:collectibles"><span>DISCOVERIES</span><strong>'+finds+'<small> / '+known+'</small></strong><div class="progressrail discovery"><div style="width:'+(known?finds/known*100:0)+'%"></div></div><small>Documented items</small></button></div>'
 +sectionTitle('Explore Leonida')+'<div class="feature-list">'+feature('library','Encyclopedia',catalog.entries.length+' library entries','info')+feature('locations','Locations','Regions and landmarks','pin')+feature('search','Search','Find information in VI Hub','search')+'</div>'
 +sectionTitle('Latest news',action('go:news','All news','text-link'))+(brief?'<button class="editorial-teaser" data-action="go:news"><div><span class="eyebrow">NEWS BRIEF</span><h3>'+esc(brief.title)+'</h3><small>'+esc(brief.source)+' · '+esc(brief.date)+'</small></div>'+icon('chevron')+'</button>':'<button class="feature" data-action="go:news"><span>View the latest headlines</span>'+icon('chevron')+'</button>')
 +sectionTitle('Your collection')+'<div class="feature-list">'+feature('bookmarks','Bookmarks','Saved and recent entries','info')+feature('offline','Offline center','Manage local content','download')+feature('journal','Discovery journal',notes.length+' personal notes','news')+feature('settings','Preferences','Updates, content and spoilers','settings')+'</div><div class="footer">VI HUB · UNOFFICIAL FAN COMPANION</div>';
}
function news(){let rows=cache[tab]||[];return heading('THE WIRE','News & updates','Editorial briefs and recent headlines.')+`${tabs(['All','Official','Community','Updates'],tab,'newsTab')}<div class="row"><div class="grow sub">Live headlines · tap to read details</div>${action('refreshNews','Refresh','chip')}</div><div class="spacer"></div>${newsPending?'<div class="note">Fetching latest headlines…</div>':''}${newsError?`<div class="note">${esc(newsError)}. ${rows.length?'Showing saved headlines.':'Try again or check your connection.'}</div>`:''}${(tab==='All'||tab==='Official'?catalog.news.map(n=>'<div class="card card-inner"><span class="eyebrow">EDITORIAL BRIEF</span><h3>'+esc(n.title)+'</h3><p>'+esc(n.summary)+'</p><span class="sub">'+esc(n.source)+' · '+esc(n.date)+'</span></div>').join(''):'')}${rows.map((r,i)=>`<article class="card">${i===0?'<img class="news-cover" src="hero.webp" alt="Concept artwork">':''}<button class="card-inner" style="width:100%;text-align:left" data-action="article:${i}"><p class="news-title">${esc(r.title)}</p><div class="sub">${esc(r.source||'External publication')}</div><div class="date">${esc(r.pubDate||'')}</div></button></article>`).join('')||(!newsPending?'<div class="empty">No live headlines loaded yet. Refresh to check for new results.</div>':'')}${action('official','Show official news')}`}
function missionRows(){
 const q=missionQuery.toLowerCase().trim(),rows=entireStory.filter(m=>(storyScope==='All chapters'||m.chapter===chapter+1)&&matchesMission(m,q,chapterFilter));return rows.length?rows.map(missionRow).join(''):'<div class="empty">No matching missions.</div>';
}
function missions(){
 const count=storyDone(),next=entireStory.find(m=>!completed.includes(m.id)),entries=custom.filter(x=>x.type===missionTab);
 const top=heading('YOUR JOURNEY','Missions','Story, optional entries and personal progress.')+'<div class="card card-inner progress-card"><div class="row"><span class="grow eyebrow">STORY CHECKLIST</span><span class="pill">'+Math.round(count/storyTotal*100)+'%</span></div><h2 class="progressnum">'+count+' <small>/ '+storyTotal+'</small></h2><div class="progressrail"><div style="width:'+count/storyTotal*100+'%"></div></div>'+(next?action('missionDetail:'+next.id,'Continue · '+esc(missionLabel(next)),'primary'):'<p class="sub">Story checklist completed.</p>')+'</div><div class="compact-links">'+action('go:completion','Overview','chip')+action('go:missionIndex','All missions','chip')+action('go:collectibles','Collectibles','chip')+'</div>'+tabs(['Story','Side','Activities'],missionTab,'missionTab');
 let panel='';
 if(missionTab==='Story'){
  panel=sectionTitle('Chapters',action('toggleNames',prefs.showMissionNames?'Hide names':'Show names','text-link'))+'<div class="chapter-stack">'+chapters.map(chapterCard).join('')+'</div>'+sectionTitle(storyScope==='All chapters'?'All story missions':'Chapter '+(chapter+1),action('storyScope',storyScope==='All chapters'?'Selected chapter':'All chapters','text-link'))+'<input id="missionQuery" class="input" placeholder="Search titles or numbers…" value="'+esc(missionQuery)+'">'+tabs(['All','Remaining','Completed','Saved'],chapterFilter,'chapterFilter')+'<div id="missionRows">'+missionRows()+'</div>'+chapterNotes();
 }else if(missionTab==='Side'){panel=sectionTitle('Optional story missions')+optionalRows.map(missionRow).join('')+'<p class="sub">Optional missions are separate from the 91-entry story checklist. Coverage follows documented launch guides.</p>'}
 else panel=sectionTitle('Discoveries and activities')+'<div class="feature-list">'+feature('collectibles','Collectible tracker','Record documented discoveries','check')+feature('goals','Personal goals','Create your own objectives','mission')+feature('journal','Journal','Keep notes on places and finds','news')+'</div>';
 return top+panel+'<details class="card personal-checklist"><summary>My own checklist · '+entries.length+'</summary><div class="card-inner">'+entries.map(x=>'<div class="listrow"><span class="grow"><strong>'+esc(x.name)+'</strong></span>'+action('toggleMission:'+x.id,completed.includes(x.id)?'✓':'','check '+(completed.includes(x.id)?'on':''))+action('removeMission:'+x.id,'Remove','chip')+'</div>').join('')+'<input id="missionName" class="input" maxlength="100" placeholder="Add your own entry">'+action('addMission','Add to checklist')+'</div></details>';
}

function locations(){
 const p=selected===null?null:places[selected];
 if(p)return regionPage(p,selected);
 return heading('EXPLORE','Places of Leonida','Browse regions and save your favorites.')+'<input class="input" id="locSearch" placeholder="Search locations…" value="'+esc(locSearch)+'">'+tabs(['All','Saved'],placeFilter,'placeFilter')+(p?'<div class="card card-inner"><h2 class="section">'+esc(p.n)+'</h2><p>'+esc(regionDescriptions[selected])+'</p><div class="sub">Region information · Rockstar’s Leonida overview</div>'+action('savePlace:'+selected,saved.includes(p.n)?'Remove from saved':'Save location')+action('go:map','View whole Leonida map','primary')+action('closePlace','Close details','chip')+'</div>':'')+'<div id="placeList">'+placeRows()+'</div>';
}
function regionPage(p,i){
 const related=regionRelated[i].map(itemById).filter(Boolean);
 return '<div class="region-hero"><img src="'+p.im+'.webp" alt=""><div><span class="eyebrow">LEONIDA REGION</span><h2>'+esc(p.n)+'</h2><p>'+esc(p.d)+'</p></div></div><div class="region-actions">'+action('regionMap:'+i,icon('map')+' Show on map','primary')+action('savePlace:'+i,saved.includes(p.n)?'Saved ✓':'Save place','secondary')+'</div><div class="card card-inner"><h3>Region overview</h3><p>'+esc(regionDescriptions[i])+'</p><p class="sub">Source: Rockstar’s Leonida overview. Artwork is illustrative.</p></div>'+sectionTitle('Explore this region')+(related.length?related.map(x=>action('entry:'+esc(x.id),'<span class="feature-icon">'+icon(x.category==='Collectibles'?'check':'pin')+'</span><span class="grow"><strong>'+esc(x.title)+'</strong><span class="sub">'+esc(x.body)+'</span></span>'+icon('chevron'),'listrow')).join(''):'<div class="note">No additional verified local entries yet.</div>')+action('closePlace','Back to all locations');
}
function placeRows(){return places.filter(p=>(p.n+' '+p.d).toLowerCase().includes(locSearch.toLowerCase())&&(placeFilter!=='Saved'||saved.includes(p.n))).map(p=>action('place:'+places.indexOf(p),'<img src="'+p.im+'.webp" alt=""><span class="grow"><strong>'+esc(p.n)+'</strong><span class="sub">'+esc(p.d)+'</span></span><span class="arrow">'+(saved.includes(p.n)?'★':'›')+'</span>','listrow')).join('')||'<div class="empty">No matching location.</div>'}
function requestMap(){
 mapState='loading';mapError='';
 if($('mapStatus'))$('mapStatus').textContent='Downloading the official printable map. First load may use approximately 45 MB.';
 if(native&&native.loadMap)native.loadMap();else{mapState='error';mapError='The map download requires the Android app.';if(screen==='map')render();}
}
function map(){
 let body=mapState==='ready'?'<div class="mapworld" id="mapworld"><img id="realMap" src="https://vihub.invalid/official-map.jpg" alt="Official Leonida map"><div id="mapTileLayer"></div>'+(regionPins?mapRegions.map((p,i)=>'<button class="pin region-pin" data-action="regionDetail:'+i+'" style="left:'+p.x*100+'%;top:'+p.y*100+'%" aria-label="'+esc(places[i].n)+'">'+icon('pin')+'</button>').join(''):'')+pins.map((p,i)=>'<button class="pin personal-pin" style="left:'+Math.max(0,Math.min(1,p.x))*100+'%;top:'+Math.max(0,Math.min(1,p.y))*100+'%" data-action="focusPin:'+i+'" aria-label="'+esc(p.name)+'">★</button>').join('')+'</div><div class="map-controls">'+action('zoomIn','+','')+action('zoomOut','−','')+action('zoomReset','⌂','')+'</div><div class="map-scale" id="mapScale">'+zoom.toFixed(1)+'×</div>':'<div class="map-loading"><div id="mapStatus" class="sub">'+esc(mapState==='error'?mapError:'Loading official Leonida map…')+'</div>'+(mapState==='error'?action('retryMap','Retry download','primary'):'')+'</div>';
 return '<div class="map-header"><span class="eyebrow">LEONIDA ATLAS</span><span class="pill">'+(mapHD?'HD MAP':mapPreviewOnly?'PREVIEW':'OFFICIAL MAP')+'</span></div>'+ (mapState==='ready'?'<div class="map-toolbar">'+action('toggleRegions',icon('pin')+' '+(regionPins?'Hide regions':'Show regions'),'chip')+action('pinMode',pinMode?'Cancel pin':'+ Add pin','chip')+action('expandAtlas',atlasExpanded?'Exit full screen':'Full screen','chip')+'</div>':'')+(pinMode?'<div class="card card-inner"><input id="pinName" class="input" maxlength="80" placeholder="Name your pin"><p class="sub">Enter the name, then tap the map.</p></div>':'')+'<div class="mapbox official-map" id="mapbox">'+body+'</div><div class="map-caption"><span>Pinch · pan · zoom up to 28×</span><span>'+ (mapHD?mapWidth+' × '+mapHeight+' px':mapPreviewOnly?'HD download unavailable':'Preparing map')+'</span></div>'+(mapPreviewOnly?action('retryMap','Retry high-resolution download'):'')+sectionTitle('Jump to a region')+'<div class="region-jumps">'+places.map((p,i)=>action('regionMap:'+i,p.n,'chip')).join('')+'</div>'+sectionTitle('Your pins')+(pins.length?personalMapRows():'<p class="sub">Add a private pin to save a discovery.</p>')+'<p class="footer">Rockstar Games printable map. Region markers are approximate placements on the poster, not precise game-world coordinates. Higher zoom cannot reveal detail beyond the original artwork.</p>';
}
function allNews(){return [...new Map(Object.values(cache).flat().filter(r=>r&&r.title).map(r=>[r.link||r.title,r])).values()]}
function searchRows(){
 const q=searchQuery.toLowerCase().trim();
 if(!q)return '<div class="empty">Search the built-in directory, mission tracker or downloaded headlines.</div>';
 const has=t=>t.toLowerCase().includes(q);
 const p=places.map((p,i)=>({p,i})).filter(({p})=>has(p.n+' '+p.d)).map(({p,i})=>action('place:'+i,'<strong>'+esc(p.n)+'</strong><span class="sub">Location · '+esc(p.d)+'</span>','listrow'));
 const c=chapters.flatMap((c,i)=>Object.entries(c.names).filter(([n,t])=>prefs.showMissionNames&&has(t)).map(([n,t])=>action('missionDetail:story-'+(i+1)+'-'+n,'<strong>'+esc(t)+'</strong><span class="sub">Chapter '+(i+1)+'</span>','listrow')));
 const n=allNews().map((r,i)=>({r,i})).filter(({r})=>has(r.title+' '+(r.source||''))).slice(0,24).map(({r,i})=>action('searchArticle:'+i,'<strong>'+esc(r.title)+'</strong><span class="sub">'+esc(r.source||'News')+'</span>','listrow'));
 const sections=[['map','Leonida map'],['missions','Mission tracker'],['news','Latest news'],['info','Game information'],['settings','Settings']].filter(([,t])=>has(t)).map(([a,t])=>action('go:'+a,esc(t),'listrow'));
 const lib=catalog.entries.filter(x=>(prefs.showMissionNames||x.category!=='Missions')&&has(x.title+' '+x.body+' '+x.category)).map(x=>action('entry:'+esc(x.id),'<strong>'+esc(x.title)+'</strong><span class="sub">'+esc(x.category)+' · '+esc(x.status)+'</span>','listrow'));return [...lib,...p,...c,...n,...sections].join('')||'<div class="empty">No local matches. Refresh the News feed for more headlines.</div>';
}
function search(){return heading('QUICK FIND','Search','Find what you need across the library and local news.')+'<div class="card card-inner"><h2 class="section" style="margin-top:0">Search VI Hub</h2><p class="sub">Search the encyclopedia, mission entries and downloaded news without leaving the app.</p><input class="input" id="query" placeholder="Search VI Hub…" maxlength="120" value="'+esc(searchQuery)+'">'+action('runSearch',icon('search')+' Search','primary')+'</div><div id="searchResults">'+searchRows()+'</div>'+action('go:news','Browse live news');}
function article(){
 const r=chosenNews;if(!r)return '<div class="empty">Article not selected.</div>';
 return '<div class="card card-inner"><span class="eyebrow">NEWS</span><h2>'+esc(r.title)+'</h2><p class="sub">'+esc(r.source||'External publication')+' · '+esc(r.pubDate||'')+'</p><p class="sub">Live headline from the named publication. Full publisher text is not available in this feed; editorial briefs are shown in News when available.</p>'+'<p class="sub">Source: '+esc(r.source||'External publication')+'</p>'+'</div>'+action('back','Back to results');
}
function info(){return `<img class="hero" src="hero.webp" alt="Concept artwork"><h2 class="section">Grand Theft Auto VI</h2><p class="sub">Explore the fictional state of Leonida and its regions. Released November 19, 2026 on PlayStation 5 and Xbox Series X|S. Explore the region directory, map and news within VI Hub.</p>${action('officialGame','Explore the world','primary')}${action('go:locations','Explore locations')}${action('go:news','Latest news')}<div class="footer">All related trademarks belong to their respective owners.</div>`}
function more(){return heading('VI HUB','Your collection','Everything else, in one place.')+`<div class="card">${[['completion','mission','Completion center','All progress in one place'],['bookmarks','info','Bookmarks','Saved and recent entries'],['goals','check','Personal goals','Your own checklist'],['offline','download','Offline center','Local content'],['locations','locations','Locations','Explore and save places'],['search','search','Search','Find in-app information'],['library','info','Encyclopedia','Your searchable game library'],['collectibles','check','Collectibles','Track documented discoveries'],['journal','news','Journal','Private notes'],['news','news','News','Editorial briefs and headlines'],['alerts','bell','Alerts','App release alerts'],['settings','settings','Settings','Updates and preferences']].map(([s,i,t,d])=>`<button class="item" style="width:100%;text-align:left" data-action="go:${s}">${icon(i)}<span class="grow"><strong>${t}</strong><span class="sub">${d}</span></span>${icon('chevron')}</button>`).join('')}</div>`}
function settings(){return heading('PREFERENCES','Make it yours','Manage your app and offline library.')+'<h2 class="section">Software update</h2><div class="card card-inner"><div class="row">'+icon('download')+'<div class="grow"><strong>VI Hub '+esc(config.version)+'</strong><div class="sub">Installed version</div></div><span class="pill">ANDROID</span></div>'+action('checkUpdate','Check for updates','primary')+'<div class="status">'+esc(updateText||'No update check yet.')+'</div>'+(update?.newer&&update?.download?action('installUpdate','Download & install update','primary'):'')+'</div><h2 class="section">Content library</h2><div class="card card-inner"><strong>Library revision '+catalog.revision+'</strong><p class="sub">'+esc(contentStatus)+' · '+esc(catalog.updated||'Bundled content')+'</p>'+action('syncCatalog','Refresh game information')+action('go:offline','Offline storage')+'</div><h2 class="section">Preferences</h2><div class="card"><div class="item">'+icon('bell')+'<span class="grow"><strong>Automatic update checks</strong><span class="sub">Check when opening VI Hub</span></span><button class="toggle" role="switch" aria-label="Automatic update checks" aria-checked="'+!!prefs.auto+'" data-action="toggleAuto"></button></div><div class="item"><span class="grow"><strong>Show mission titles</strong><span class="sub">Optional story spoilers</span></span><button class="toggle" role="switch" aria-label="Show mission titles" aria-checked="'+!!prefs.showMissionNames+'" data-action="toggleNames"></button></div></div><h2 class="section">About</h2><div class="card card-inner"><strong>VI Hub · Unofficial fan companion</strong><p class="sub">Map data and saved progress stay on this device. Live news, content refresh and software updates require an internet connection.</p>'+action('clearNews','Clear cached headlines')+'</div>'}
function alerts(){return `<div class="card card-inner"><div class="row">${icon('bell')}<div class="grow"><strong>App release alerts</strong><div class="sub">${esc(updateText||'No release checks yet.')}</div></div></div>${action('checkUpdate','Check for updates','primary')}${action('go:settings','Update settings')}</div><div class="note">Update alerts appear when you open the app or check manually. Background push notifications are not enabled.</div>`}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toast.tm);toast.tm=setTimeout(()=>$('toast').style.display='none',4200)}
function browse(){toast('Information is shown inside VI Hub.')}
function webSearch(q){searchQuery=(q||'').trim();if(screen==='search')render();else go('search')}
function loadNews(){newsPending=true;newsError='';if(screen==='news')render();if(native)native.news(tab);else{newsPending=false;newsError='Live news requires the Android app';render()}}
function checkUpdate(){update=null;updateText='Checking for updates…';if(['settings','alerts'].includes(screen))render();if(native)native.checkUpdate();else{updateText='Update checks require Android.';render()}}
function initMap(){
 const box=$('mapbox'),world=$('mapworld'),img=$('realMap'),layer=$('mapTileLayer');if(!box||!world)return;
 let w=0,h=0,tiles=new Map(),tileFrame=0;
 const fit=()=>{const ratio=mapHD?mapWidth/mapHeight:img?.naturalWidth&&img?.naturalHeight?img.naturalWidth/img.naturalHeight:5775/7900;w=Math.min(box.clientWidth,box.clientHeight*ratio);h=w/ratio;world.style.width=w+'px';world.style.height=h+'px';world.style.left=(box.clientWidth-w)/2+'px';world.style.top=(box.clientHeight-h)/2+'px';};
 const refreshTiles=()=>{
 tileFrame=0;if(!world.isConnected)return;if(!layer||!mapHD||zoom<2){for(const el of tiles.values())el.remove();tiles.clear();return;}
 const rect=world.getBoundingClientRect(),view=box.getBoundingClientRect(),size=1024;
 const minX=Math.max(0,Math.floor((view.left-rect.left)/rect.width*mapWidth/size)),maxX=Math.min(Math.ceil(mapWidth/size)-1,Math.floor((view.right-rect.left)/rect.width*mapWidth/size));
 const minY=Math.max(0,Math.floor((view.top-rect.top)/rect.height*mapHeight/size)),maxY=Math.min(Math.ceil(mapHeight/size)-1,Math.floor((view.bottom-rect.top)/rect.height*mapHeight/size));
 const wanted=new Set();for(let y=minY;y<=maxY;y++)for(let x=minX;x<=maxX;x++){const key=x+'/'+y;wanted.add(key);if(tiles.has(key))continue;const t=document.createElement('img');t.className='map-tile';t.alt='';t.style.left=(100*x*size/mapWidth)+'%';t.style.top=(100*y*size/mapHeight)+'%';t.style.width=(100*Math.min(size,mapWidth-x*size)/mapWidth)+'%';t.style.height=(100*Math.min(size,mapHeight-y*size)/mapHeight)+'%';t.onload=()=>t.style.opacity='1';t.src='https://vihub.invalid/map-tile/'+key;layer.appendChild(t);tiles.set(key,t);}
 for(const [key,t] of tiles)if(!wanted.has(key)){t.remove();tiles.delete(key);}
 };
 const draw=()=>{if(!world.isConnected)return;let maxX=Math.max(0,(w*zoom-box.clientWidth)/2),maxY=Math.max(0,(h*zoom-box.clientHeight)/2);pan.x=Math.max(-maxX,Math.min(maxX,pan.x));pan.y=Math.max(-maxY,Math.min(maxY,pan.y));world.style.transform='translate('+pan.x+'px,'+pan.y+'px) scale('+zoom+')';world.style.setProperty('--inverse-zoom',1/zoom);if($('mapScale'))$('mapScale').textContent=zoom.toFixed(1)+'×';if(!tileFrame)tileFrame=requestAnimationFrame(refreshTiles);};
 fit();mapDraw=draw;if(pendingRegion!==null){const p=mapRegions[pendingRegion];zoom=5;pan={x:(.5-p.x)*w*zoom,y:(.5-p.y)*h*zoom};pendingRegion=null;}draw();
 let pointers=new Map(),previous=null;
 const midpoint=()=>{let [a,b]=pointers.values();return a&&b?{x:(a.x+b.x)/2,y:(a.y+b.y)/2,d:Math.hypot(a.x-b.x,a.y-b.y)}:null};
 if(img){img.addEventListener('load',()=>{fit();draw()},{once:true});img.addEventListener('error',()=>{mapState='error';mapError='Could not display the map.';if(screen==='map')render()},{once:true});}
 box.addEventListener('click',e=>{if(!pinMode||e.target.closest('button'))return;const rect=world.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width,y=(e.clientY-rect.top)/rect.height;if(x>=0&&x<=1&&y>=0&&y<=1)addMapPin(x,y)});
 box.addEventListener('pointerdown',e=>{if(pinMode||e.target.closest('button'))return;box.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});previous=midpoint()});
 box.addEventListener('pointermove',e=>{const prev=pointers.get(e.pointerId);if(!prev)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===1){pan.x+=e.clientX-prev.x;pan.y+=e.clientY-prev.y;}else if(pointers.size===2){const now=midpoint(),rect=box.getBoundingClientRect();if(previous&&previous.d>0){const old=zoom;zoom=Math.max(1,Math.min(28,zoom*now.d/previous.d));const ratio=zoom/old,cx=rect.left+rect.width/2,cy=rect.top+rect.height/2;pan.x=(pan.x-(previous.x-cx))*ratio+(now.x-cx);pan.y=(pan.y-(previous.y-cy))*ratio+(now.y-cy);}previous=now;}draw();});
 const up=e=>{pointers.delete(e.pointerId);previous=midpoint()};box.addEventListener('pointerup',up);box.addEventListener('pointercancel',up);
}
window.onNative=(e,p)=>{if(e==='catalog'){catalogPending=false;if(validCatalog(p)&&p.revision>=catalog.revision){catalog=p;set('catalog-v1',p);contentStatus='Content up to date';}else contentStatus=p.error||'Keeping the current library';if(['home','library','entry','collectibles','settings','search','news','offline','completion','bookmarks'].includes(screen))render();return;}if(e==='map'){mapState=p.error?'error':'ready';mapError=p.error||'';mapHD=!!p.hd;mapPreviewOnly=p.state==='preview';if(p.width>0&&p.height>0){mapWidth=p.width;mapHeight=p.height;}if(screen==='map')render();return;}if(e==='news'){newsPending=false;if(p.error)newsError=p.error;else{cache[p.filter]=p.items;set('newsCache',cache)}if(screen==='news')render();}if(e==='update'){update=p.error?null:p;updateText=p.error?p.error:p.newer?`Version ${p.tag} is available.${p.download?'':' No APK attached.'}\n${p.notes||''}`:`You're up to date (${config.version}).`;if(['settings','alerts'].includes(screen))render();else if(p.newer)toast('New app version available — open Settings.');}if(e==='install'){updateText=p.error||p.message;if(screen==='settings')render();toast(updateText)}if(e==='notice')toast(p.error||'Request failed')};
const quicks=['Latest news','Mission titles and story summaries','Vice City landmarks','Leonida map','Performance and accessibility settings','Official game updates'];
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let [a,...parts]=b.dataset.action.split(':'),v=parts.join(':');switch(a){case'chooseChapter':chapter=Math.max(0,Math.min(4,Number(v)||0));missionTab='Story';storyScope='Chapter';missionQuery='';chapterFilter='All';if(screen!=='missions'){go('missions');$('missionQuery')?.scrollIntoView({block:'center'});return;}render();$('missionQuery')?.scrollIntoView({block:'center'});return;case'storyScope':storyScope=storyScope==='All chapters'?'Chapter':'All chapters';break;case'chapterFilter':chapterFilter=v;break;case'collectionFilter':collectionFilter=v;break;case'indexFilter':indexFilter=v;break;case'missionDetail':if(!missionRecords.some(x=>x.id===v))return;if(screen==='missionDetail'&&$('missionNote')){missionNotes[currentMission]=$('missionNote').value;set('missionNotes',missionNotes);}currentMission=v;if(screen==='missionDetail'){render();$('screen').scrollTop=0;return;}return go('missionDetail');case'favoriteMission':if(screen==='missionDetail'&&$('missionNote')){missionNotes[currentMission]=$('missionNote').value;set('missionNotes',missionNotes);}missionFavorites=missionFavorites.includes(v)?missionFavorites.filter(x=>x!==v):[...missionFavorites,v];set('missionFavorites',missionFavorites);break;case'saveMissionNote':missionNotes[currentMission]=$('missionNote').value;set('missionNotes',missionNotes);toast('Note saved.');return;case'addGoal':{const name=$('goalName').value.trim();if(!name)return toast('Add a goal first.');goals.push({title:name,done:false});set('goals',goals);break;}case'toggleGoal':if(goals[Number(v)])goals[Number(v)].done=!goals[Number(v)].done;set('goals',goals);break;case'removeGoal':goals.splice(Number(v),1);set('goals',goals);break;case'expandAtlas':atlasExpanded=!atlasExpanded;break;case'toggleRegions':regionPins=!regionPins;break;case'regionMap':pendingRegion=Number(v);if(screen==='map'){$('screen').scrollTop=0;break;}return go('map');case'regionDetail':selected=Number(v);return go('locations');case'libraryTab':libraryTab=v;break;case'entry':detailId=v;recentEntries=[v,...recentEntries.filter(x=>x!==v)].slice(0,12);set('recentEntries',recentEntries);if(screen==='entry')break;return go('entry');case'saveEntry':librarySaved=librarySaved.includes(v)?librarySaved.filter(x=>x!==v):[...librarySaved,v];set('librarySaved',librarySaved);break;case'found':found=found.includes(v)?found.filter(x=>x!==v):[...found,v];set('foundItems',found);break;case'syncCatalog':return syncCatalog();case'pinMode':pinMode=!pinMode;break;case'focusPin':{const p=pins[Number(v)],w=$('mapworld');if(p&&w){zoom=7;pan={x:(0.5-p.x)*w.clientWidth*zoom,y:(0.5-p.y)*w.clientHeight*zoom};mapDraw?.();$('screen').scrollTop=0;toast(p.name)}return;}case'deletePin':pins.splice(Number(v),1);set('personalPins',pins);break;case'addNote':{let title=$('noteTitle').value.trim(),body=$('noteBody').value.trim();if(!title||!body)return toast('Enter a title and note.');notes.unshift({title,body,date:new Date().toLocaleDateString()});set('journal',notes);break}case'removeNote':notes.splice(Number(v),1);set('journal',notes);break;case'go':return go(v);case'back':return window.backScreen();case'newsTab':tab=v;return loadNews();case'refreshNews':return loadNews();case'article':chosenNews=cache[tab]?.[Number(v)];return go('article');case'searchArticle':chosenNews=allNews()[Number(v)];return go('article');case'sourceArticle':return;case'official':tab='Official';return loadNews();case'officialGame':return go('locations');case'officialPlaces':return go('locations');case'communityMap':return go('map');case'missionTab':missionTab=v;break;case'chapter':chapter=Number(v.split(' ')[1])-1;missionQuery='';break;case'openChapter':chapter=Number(v);missionTab='Story';missionQuery='';return go('missions');case'toggleNames':prefs.showMissionNames=!prefs.showMissionNames;set('prefs',prefs);break;case'findMissions':return go('missions');case'addMission':{let n=$('missionName').value.trim();if(!n)return toast('Enter a name first.');custom.push({name:n,type:missionTab,id:String(Date.now())});set('custom',custom);break}case'toggleMission':if(screen==='missionDetail'&&$('missionNote')){missionNotes[currentMission]=$('missionNote').value;set('missionNotes',missionNotes);}completed=completed.includes(v)?completed.filter(x=>x!==v):[...completed,v];set('completed',completed);break;case'removeMission':custom=custom.filter(x=>x.id!==v);completed=completed.filter(x=>x!==v);set('custom',custom);set('completed',completed);break;case'place':selected=Number(v);if(screen==='locations'){$('screen').scrollTop=0;break;}return go('locations');case'closePlace':selected=null;$('screen').scrollTop=0;break;case'placeFilter':placeFilter=v;break;case'retryMap':mapState='idle';break;case'mapPin':selected=Number(v);break;case'mapFilter':mapFilter=v;break;case'savePlace':{let n=places[Number(v)].n;saved=saved.includes(n)?saved.filter(x=>x!==n):[...saved,n];set('saved',saved);break}case'findPlace':selected=Number(v);return go('locations');case'zoomIn':{const old=zoom;zoom=Math.min(28,zoom*1.5);pan.x*=zoom/old;pan.y*=zoom/old;mapDraw?.();return;}case'zoomOut':{const old=zoom;zoom=Math.max(1,zoom/1.5);pan.x*=zoom/old;pan.y*=zoom/old;mapDraw?.();return;}case'zoomReset':zoom=1;pan={x:0,y:0};mapDraw?.();return;case'quick':return webSearch(quicks[Number(v)]);case'runSearch':return webSearch($('query').value);case'checkUpdate':return checkUpdate();case'installUpdate':if(native&&update?.newer&&update?.download){native.installUpdate();}return;case'toggleAuto':prefs.auto=!prefs.auto;set('prefs',prefs);break;case'clearNews':cache={};set('newsCache',cache);toast('News cache cleared.');break;default:return}render()});
document.addEventListener('input',e=>{if(e.target.id==='collectionQuery'){collectionQuery=e.target.value;$('collectionRows').innerHTML=collectibleRows()}if(e.target.id==='indexQuery'){indexQuery=e.target.value;$('indexRows').innerHTML=indexRows()}if(e.target.id==='libraryQuery'){libraryQuery=e.target.value;$('libraryRows').innerHTML=libraryRows()}if(e.target.id==='locSearch'){locSearch=e.target.value;$('placeList').innerHTML=placeRows()}if(e.target.id==='missionQuery'){missionQuery=e.target.value;$('missionRows').innerHTML=missionRows()}if(e.target.id==='query'){searchQuery=e.target.value;$('searchResults').innerHTML=searchRows()}});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='query')webSearch(e.target.value);if(e.key==='Enter'&&e.target.id==='missionName')document.querySelector('[data-action="addMission"]').click()});render();if(native){syncCatalog();if(prefs.auto)checkUpdate();}
